.tool-logos-section {
  margin: 75px 0 110px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.tool-logos-title {
  margin: 0 0 32px;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  opacity: 0.5;
}

.tool-groups {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 40px;
}

.tool-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.tool-group-label {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--vp-c-text-2);
}

.tool-logos {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: stretch;
  gap: 4px;
  padding: 6px;
  border: 1px solid var(--vp-c-divider);
  border-radius: 12px;
}

.tool-chip {
